import{_ as i,o as a,c as e,ag as t}from"./chunks/framework.DEqXEGcv.js";const k=JSON.parse('{"title":"Cascade","description":"","frontmatter":{},"headers":[],"relativePath":"composition/cascade.md","filePath":"composition/cascade.md"}'),n={name:"composition/cascade.md"};function l(h,s,p,r,d,c){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="cascade" tabindex="-1">Cascade <a class="header-anchor" href="#cascade" aria-label="Permalink to &quot;Cascade&quot;">​</a></h1><p><code>CASCADE</code> propagates a transition downward through the composition tree. When a parent transitions with CASCADE, all of its children are recursively transitioned to a terminal state.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><p>Append <code>CASCADE</code> to a TRANSITION command:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRANSITION Order </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;01J5X7K2P3Q4R5S6T7U8V9W0XY&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled CASCADE</span></span></code></pre></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When a transition includes CASCADE, the engine:</p><ol><li>Transitions the parent instance to the target state (guards, mutations, and actions execute as normal)</li><li>Finds all children of the parent instance</li><li>For each child that is not already in a terminal state, attempts to transition it to its <strong>first declared terminal state</strong></li><li>Recursively repeats step 2-3 for each child&#39;s children</li></ol><h2 id="first-terminal-state" tabindex="-1">First Terminal State <a class="header-anchor" href="#first-terminal-state" aria-label="Permalink to &quot;First Terminal State&quot;">​</a></h2><p>CASCADE transitions each child to the <strong>first</strong> terminal state declared in the child machine&#39;s definition. The ordering in the <code>TERMINAL STATES</code> block determines which state is chosen:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE LineItem (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { confirmed, cancelled }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>When an Order is cancelled with CASCADE, each LineItem child will be transitioned to <code>confirmed</code> -- the first terminal state. If you want cancellation to propagate as cancellation, put <code>cancelled</code> first:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE LineItem (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { cancelled, confirmed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Now CASCADE will attempt to transition each LineItem to <code>cancelled</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The order of terminal states matters for CASCADE. Put the &quot;default shutdown&quot; state first if you want CASCADE to use it. In most designs, <code>cancelled</code> should be listed first in TERMINAL STATES when the machine participates in a CASCADE cancellation pattern.</p></div><h2 id="guard-behavior" tabindex="-1">Guard Behavior <a class="header-anchor" href="#guard-behavior" aria-label="Permalink to &quot;Guard Behavior&quot;">​</a></h2><p>CASCADE still evaluates guards on each child transition. If the first terminal state&#39;s transition has a guard that fails, that child remains in its current state. CASCADE does not try the second terminal state.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE LineItem (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { cancelled, confirmed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ANY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      EXCEPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { confirmed }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      GUARD : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ACTOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>If CASCADE triggers without an actor (which is typical), the guard <code>ACTOR.role == &quot;admin&quot;</code> will fail, and the LineItem stays in its current state.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>CASCADE only attempts the <strong>first</strong> terminal state. If its guard fails, the child stays where it is. Design your terminal transitions with this in mind -- guards on cascade-targeted transitions should be permissive, or the cascade will silently leave children behind.</p></div><h2 id="recursive-depth" tabindex="-1">Recursive Depth <a class="header-anchor" href="#recursive-depth" aria-label="Permalink to &quot;Recursive Depth&quot;">​</a></h2><p>CASCADE is recursive. If a child has its own children, those grandchildren are also cascaded:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Order (cancelled via CASCADE)</span></span>
<span class="line"><span>  |-- LineItem_1 -&gt; cancelled</span></span>
<span class="line"><span>  |-- LineItem_2 -&gt; cancelled</span></span>
<span class="line"><span>  |-- Shipment -&gt; lost</span></span>
<span class="line"><span>        |-- TrackingEvent_1 -&gt; archived</span></span>
<span class="line"><span>        |-- TrackingEvent_2 -&gt; archived</span></span></code></pre></div><p>Each level independently resolves to the first terminal state of that machine type.</p><h2 id="example-cancelling-an-order" tabindex="-1">Example: Cancelling an Order <a class="header-anchor" href="#example-cancelling-an-order" aria-label="Permalink to &quot;Example: Cancelling an Order&quot;">​</a></h2><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Order (</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DATA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    customer : REF(Customer) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    total    : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MONEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(USD)    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    notes    : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">           -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPTIONAL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  STATES { draft, placed, paid, payment_failed, fulfilled, shipped, delivered, cancelled, returned }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> draft</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { delivered, cancelled, returned }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    items    : LIST(LineItem)      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    shipment : OPTIONAL(Shipment)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ANY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      EXCEPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { shipped, delivered, returned }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Cancelling with CASCADE:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRANSITION Order </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;01J5X7K2P3Q4R5S6T7U8V9W0XY&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled CASCADE</span></span></code></pre></div><p>This will:</p><ol><li>Transition the Order to <code>cancelled</code></li><li>Find all LineItem children -- transition each to their first terminal state</li><li>Find the Shipment child (if any) -- transition it to its first terminal state</li><li>If the Shipment has children, cascade to them as well</li></ol><h2 id="cascade-with-other-clauses" tabindex="-1">CASCADE with Other Clauses <a class="header-anchor" href="#cascade-with-other-clauses" aria-label="Permalink to &quot;CASCADE with Other Clauses&quot;">​</a></h2><p>CASCADE can be combined with other transition clauses:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TRANSITION Order </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;01J5...&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled CASCADE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  WITH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { cancellation_reason: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Customer request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MEMO </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Cancelled per customer phone call&quot;</span></span></code></pre></div><p>The AS, WITH, and MEMO clauses apply to the parent transition only. Child transitions triggered by CASCADE execute without actor, data, or memo context.</p><h2 id="when-not-to-cascade" tabindex="-1">When Not to CASCADE <a class="header-anchor" href="#when-not-to-cascade" aria-label="Permalink to &quot;When Not to CASCADE&quot;">​</a></h2><p>CASCADE is a blunt instrument. It is best suited for shutdown scenarios:</p><ul><li>Cancelling an order and all its line items</li><li>Aborting a pipeline and all its stages</li><li>Archiving a project and all its tasks</li></ul><p>For more nuanced scenarios where children should transition to different states based on their current state, use explicit transitions on each child instead of CASCADE.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>CASCADE is a command-time option, not a machine definition feature. The machine does not declare &quot;this transition always cascades.&quot; The caller decides whether to include CASCADE when issuing the TRANSITION command.</p></div>`,39)])])}const E=i(n,[["render",l]]);export{k as __pageData,E as default};
